import{obterCadastros}from"./storage.js";import{formatDistanceToNow}from"https://cdn.jsdelivr.net/npm/date-fns@3.6.0/+esm";import{ptBR}from"https://cdn.jsdelivr.net/npm/date-fns@3.6.0/locale/+esm";const escapeHTML=a=>String(a).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#39;"),ONG={sobre:"A ONG Mãos Solidárias é uma organização do terceiro setor fundada em 2015, dedicada a combater a insegurança alimentar e promover a inclusão social de famílias em situação de vulnerabilidade. Atuamos por meio de campanhas de doação, capacitação profissional e apoio educacional, contando com o trabalho voluntário de centenas de pessoas em todo o país.",email:"contato@maossolidarias.org",telefone:"(11) 3333-4444",telefoneLink:"+551133334444",endereco:"Rua da Esperança, 123 - São Paulo/SP"},CATEGORIAS={voluntariado:"Voluntariado",doacao:"Doação"},projetos=[{categoria:"voluntariado",titulo:"Atuação em Campo",descricao:"Voluntários que desejam atuar diretamente com as comunidades atendidas participam da distribuição de doações, oficinas educativas e eventos de mobilização social nos bairros parceiros."},{categoria:"voluntariado",titulo:"Apoio Administrativo",descricao:"Para quem prefere contribuir remotamente, oferecemos frentes de apoio em organização de campanhas, comunicação nas redes sociais e gestão de cadastro de doadores."},{categoria:"doacao",titulo:"Doação de Alimentos",descricao:"Nossa campanha permanente de arrecadação de alimentos não perecíveis conta com pontos de coleta em diversos bairros da cidade. Consulte o ponto mais próximo de você na seção de cadastro.",detalhes:{id:"modal-alimentos",texto:"Os pontos de coleta funcionam de segunda a sábado, das 9h às 18h. Aceitamos alimentos não perecíveis dentro do prazo de validade, embalados e identificados. Toda a arrecadação é redistribuída em até 72 horas para as famílias cadastradas no programa."}},{categoria:"doacao",titulo:"Doação Financeira",descricao:"Contribuições financeiras, recorrentes ou pontuais, sustentam nossos programas de capacitação profissional e apoio educacional às famílias atendidas."}],gruposCadastro=[{atributo:'id="user-details"',legenda:"Dados do Usuário",campos:[{id:"nome",rotulo:"Nome completo:",tipo:"text",placeholder:"Digite seu nome completo",autocomplete:"name"},{id:"nascimento",rotulo:"Data de nascimento:",tipo:"date",autocomplete:"bday"},{id:"cpf",rotulo:"CPF:",tipo:"text",pattern:"\\d{3}\\.\\d{3}\\.\\d{3}-\\d{2}",placeholder:"000.000.000-00",title:"Formato esperado: 000.000.000-00"}]},{atributo:'id="contact-info"',legenda:"Informações de Contato",campos:[{id:"email",rotulo:"E-mail:",tipo:"email",placeholder:"seuemail@exemplo.com",autocomplete:"email"},{id:"telefone",rotulo:"Telefone:",tipo:"tel",autocomplete:"tel",pattern:"\\(\\d{2}\\) \\d{4,5}-\\d{4}",placeholder:"(00) 00000-0000",title:"Formato esperado: (00) 00000-0000"},{id:"cep",rotulo:"CEP:",tipo:"text",autocomplete:"postal-code",pattern:"\\d{5}-\\d{3}",placeholder:"00000-000",title:"Formato esperado: 00000-000"},{id:"endereco",rotulo:"Endereço:",tipo:"text",placeholder:"Rua, número, bairro",autocomplete:"street-address"},{id:"cidade",rotulo:"Cidade:",tipo:"text",placeholder:"Sua cidade",autocomplete:"address-level2"},{id:"estado",rotulo:"Estado:",tipo:"text",placeholder:"UF",maxlength:2}]},{atributo:'class="preferences"',legenda:"Preferências",campos:[{id:"area",rotulo:"Área de interesse:",tipo:"select",opcoes:[{valor:"voluntariado",texto:"Voluntariado"},{valor:"doacao",texto:"Doação"}]}]}],cardProjeto=({categoria:a,titulo:o,descricao:e,detalhes:t})=>`\n    <article class="project col-6">\n        <div>\n            <span class="badge badge-${a}">${CATEGORIAS[a]}</span>\n            <h3>${escapeHTML(o)}</h3>\n            <p>${escapeHTML(e)}</p>\n        </div>\n        ${t?`<button type="button" class="btn-link" data-abrir-modal="${t.id}">Ver detalhes da campanha</button>`:""}\n    </article>\n`,modalDetalhes=({titulo:a,detalhes:o})=>`\n    <div id="${o.id}" class="modal-overlay">\n        <div class="modal" role="dialog" aria-modal="true" aria-labelledby="${o.id}-titulo">\n            <button type="button" class="modal-close" data-fechar-modal aria-label="Fechar detalhes da campanha">&times;</button>\n            <h3 id="${o.id}-titulo">${escapeHTML(a)}</h3>\n            <p>${escapeHTML(o.texto)}</p>\n        </div>\n    </div>\n`,secaoProjetos=(a,o,e)=>{const t=projetos.filter(a=>a.categoria===e);return`\n        <section id="${a}">\n            <h2>${o}</h2>\n            <div class="grid">\n                ${t.map(cardProjeto).join("")}\n            </div>\n            ${t.filter(a=>a.detalhes).map(modalDetalhes).join("")}\n        </section>\n    `},campoFormulario=a=>{const o="select"===a.tipo?`<select id="${a.id}" name="${a.id}" required>\n               ${a.opcoes.map(a=>`<option value="${a.valor}">${a.texto}</option>`).join("")}\n           </select>`:`<input type="${a.tipo}" id="${a.id}" name="${a.id}"\n               ${a.placeholder?`placeholder="${escapeHTML(a.placeholder)}"`:""}\n               ${a.pattern?`pattern="${escapeHTML(a.pattern)}"`:""}\n               ${a.title?`title="${escapeHTML(a.title)}"`:""}\n               ${a.maxlength?`maxlength="${a.maxlength}"`:""}\n               ${a.autocomplete?`autocomplete="${a.autocomplete}"`:""}\n               required>`;return`\n        <div class="form-group">\n            <label for="${a.id}">${a.rotulo}</label>\n            ${o}\n        </div>\n    `},grupoFormulario=a=>`\n    <fieldset ${a.atributo}>\n        <legend>${a.legenda}</legend>\n        ${a.campos.map(campoFormulario).join("")}\n    </fieldset>\n`,itemCadastroSalvo=({nome:a,area:o,dataCadastro:e})=>{const t=formatDistanceToNow(new Date(e),{addSuffix:!0,locale:ptBR});return`\n        <li>\n            ${escapeHTML(a)} — <span class="badge badge-${o}">${CATEGORIAS[o]}</span>\n            <small class="cadastro-tempo">cadastrado ${t}</small>\n        </li>\n    `},listaCadastrosSalvos=()=>{const a=obterCadastros();return`\n        <section id="lista-cadastros">\n            <h3>Cadastros Realizados (${a.length})</h3>\n            ${a.length?`<ul class="lista-cadastros">${a.map(itemCadastroSalvo).join("")}</ul>`:"<p>Nenhum cadastro salvo neste navegador ainda.</p>"}\n        </section>\n    `};export const templates={home:()=>`\n        <section id="apresentacao">\n            <h2>Quem Somos</h2>\n            <div class="grid">\n                <div class="col-6">\n                    <img src="../imagens/equipe.jpg" alt="Voluntários da ONG Mãos Solidárias distribuindo cestas de doações para famílias em situação de vulnerabilidade">\n                </div>\n                <div class="col-6">\n                    <p>${ONG.sobre}</p>\n                </div>\n            </div>\n        </section>\n\n        <section id="contato">\n            <h2>Fale Conosco</h2>\n            <address>\n                <p>E-mail: <a href="mailto:${ONG.email}">${ONG.email}</a></p>\n                <p>Telefone: <a href="tel:${ONG.telefoneLink}">${ONG.telefone}</a></p>\n                <p>Endereço: ${ONG.endereco}</p>\n            </address>\n        </section>\n    `,projetos:()=>`\n        ${secaoProjetos("voluntariado","Como Ser Voluntário","voluntariado")}\n        ${secaoProjetos("doacoes","Campanhas de Doação","doacao")}\n    `,cadastro:()=>`\n        <h2>Cadastre-se</h2>\n\n        <div class="alert alert-info">\n            <strong>Atenção:</strong> todos os campos marcados como obrigatórios devem ser\n            preenchidos corretamente antes do envio do formulário.\n        </div>\n\n        <form id="form-cadastro" novalidate>\n            ${gruposCadastro.map(grupoFormulario).join("")}\n\n            <div class="form-actions">\n                <button type="submit">Cadastrar</button>\n            </div>\n        </form>\n\n        ${listaCadastrosSalvos()}\n    `,notFound:()=>'\n        <section id="nao-encontrado">\n            <h2>Página não encontrada</h2>\n            <p><a href="#/">Voltar para o início</a></p>\n        </section>\n    '};